import{_ as a,o as l,c as i,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Day CERN 2019: Scale out Sync & Share with Seafile on Ceph - Sönke Schippmann","description":"","frontmatter":{"title":"Ceph Day CERN 2019: Scale out Sync & Share with Seafile on Ceph - Sönke Schippmann","date":"2020-08-25T00:00:00.000Z","updated":"2020-08-26T00:00:00.000Z","tags":["Ceph","分布式存储","Seafile","同步与共享","Sönke Schippmann"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Day_CERN_2019_-_Scale_out_Sync_Share_with_Seafile_on_Ceph_-_Sonke_Schippmann.md","filePath":"posts/2020/Ceph_Day_CERN_2019_-_Scale_out_Sync_Share_with_Seafile_on_Ceph_-_Sonke_Schippmann.md","lastUpdated":1780459816000}'),t={name:"posts/2020/Ceph_Day_CERN_2019_-_Scale_out_Sync_Share_with_Seafile_on_Ceph_-_Sonke_Schippmann.md"};function h(o,e,r,p,_,S){return l(),i("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-day-cern-2019-seafile在ceph上的扩展同步与共享" tabindex="-1">会议主题：Ceph Day CERN 2019 - Seafile在Ceph上的扩展同步与共享 <a class="header-anchor" href="#会议主题-ceph-day-cern-2019-seafile在ceph上的扩展同步与共享" aria-label="Permalink to &quot;会议主题：Ceph Day CERN 2019 - Seafile在Ceph上的扩展同步与共享&quot;">​</a></h4><h4 id="会议时间-2019年-具体时间未提供" tabindex="-1">会议时间：2019年（具体时间未提供） <a class="header-anchor" href="#会议时间-2019年-具体时间未提供" aria-label="Permalink to &quot;会议时间：2019年（具体时间未提供）&quot;">​</a></h4><h4 id="会议地点-cern-具体地点未提供" tabindex="-1">会议地点：CERN（具体地点未提供） <a class="header-anchor" href="#会议地点-cern-具体地点未提供" aria-label="Permalink to &quot;会议地点：CERN（具体地点未提供）&quot;">​</a></h4><h4 id="参会人员-sonke-schippmann-布莱梅大学代表" tabindex="-1">参会人员：Sönke Schippmann，布莱梅大学代表 <a class="header-anchor" href="#参会人员-sonke-schippmann-布莱梅大学代表" aria-label="Permalink to &quot;参会人员：Sönke Schippmann，布莱梅大学代表&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Ceph集群介绍</strong></p><ul><li>布莱梅大学运行一个900毫拍字节（MilliPetabyte）的Ceph集群，对Ceph在不同工作负载下的性能表示满意。</li></ul></li><li><p><strong>Seafile同步与共享系统</strong></p><ul><li>Seafile是一个开源的同步与共享系统，类似于ownCloud和NextCloud，但性能更优，硬件需求更低。</li><li>布莱梅大学拥有约9000名Seafile用户，其中3000名在过去几个月内活跃，存储了35TB的数据，分布在1.5亿个对象中。</li></ul></li><li><p><strong>Seafile的系统硬件配置</strong></p><ul><li>Seafile运行在一个配置较低的虚拟机上，仅使用8个虚拟CPU和32GB RAM，大部分时间处于空闲状态。</li></ul></li><li><p><strong>存储迁移策略</strong></p><ul><li>Seafile目前使用基于RBD卷的ZFS文件系统进行存储，正在迁移至Ceph的S3存储。</li><li>迁移的主要目的是利用Ceph的S3存储后端，通过Rados Gateway实现更高效的存储管理。</li></ul></li><li><p><strong>Seafile的存储后端配置</strong></p><ul><li>Seafile支持多种存储后端，包括文件系统存储、S3存储、OpenStack和Ceph直接存储。</li><li>对于S3存储，需要配置三个桶，并设置S3用户和放置目标规则，以更好地管理数据池。</li></ul></li><li><p><strong>Seafile的配置文件调整</strong></p><ul><li>需要修改Seafile的配置文件，包括后端服务器和前端服务器的配置，以及一个JSON文件来指定存储目标。</li><li>对于已有用户数据的情况，需要确保默认存储设置为文件系统存储，以避免数据访问问题。</li></ul></li><li><p><strong>数据迁移策略</strong></p><ul><li>由于Seafile提供的迁移脚本仅支持离线迁移，布莱梅大学决定自行开发在线迁移脚本，以避免长时间的服务中断。</li><li>迁移工作已经进行了约三个月，预计年底前完成。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认Seafile从文件系统存储迁移至Ceph S3存储的计划。</li><li>确认自行开发的在线迁移脚本的使用，以减少服务中断时间。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续监控和调整迁移过程中的性能和稳定性。</li><li>完成迁移后，评估新存储系统的性能和用户反馈。</li><li>更新和维护Seafile系统的配置文件和文档，确保未来的可维护性。</li></ul><h4 id="附件" tabindex="-1">附件： <a class="header-anchor" href="#附件" aria-label="Permalink to &quot;附件：&quot;">​</a></h4><ul><li>迁移脚本和配置文件示例链接。</li><li>Seafile和Ceph系统的相关文档和更新。</li></ul>',13)])])}const u=a(t,[["render",h]]);export{c as __pageData,u as default};
